import { THEME_MODES } from "@rapid7/rds-theme-metadata-provider";
import { darkShadows } from "./darkShadows";
import { lightShadows } from "./lightShadows";
const shadowMap = {
    [THEME_MODES.DARK]: darkShadows,
    [THEME_MODES.LIGHT]: lightShadows,
};
/**
 * Get the shadows array for the given theme mode
 * @param {ThemeMode} themeMode - The theme mode
 * @returns {Shadows} The shadows array
 */
export const getShadows = (themeMode) => {
    return shadowMap[themeMode];
};
